// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0xA11CE);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 wei}();
        vm.prank(alice);
        // The reference require(callResult) uses less gas; the mutant require(callResult, "transfer failed") uses more gas.
        // We forward exactly 3000 gas so the reference succeeds and the mutant reverts.
        (bool success,) = address(c).call{gas: 3000}(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(success);
    }
}

