// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract GasConsumer {
    uint public x;
    receive() external payable {
        uint i = 0;
        while (i < 100) {
            x += i;
            i++;
        }
        assembly { gas() }
    }
}

contract InvMutTest is Test {
    C c;
    GasConsumer receiver;

    function setUp() public {
        c = new C();
        receiver = new GasConsumer();
    }

    function testRegression_property() public {
        address receiverAddr = address(receiver);
        vm.deal(receiverAddr, 1 wei);
        vm.prank(receiverAddr);
        c.deposit{value: 1 wei}();

        uint initialBalance = address(c).balance;

        vm.prank(receiverAddr);
        (bool success, ) = address(c).call{gas: 50000}(abi.encodeWithSignature("withdrawAll()"));

        assertTrue(!success);
    }
}

